const repo = '/home/user/code/EllyaOrg/projects/dalimaray/droid-observatory';
const calls = {
  settings: () => tools.Read({ file_path: `${repo}/.factory/settings.json` }),
  hooksDir: () => tools.Execute({ summary: 'List hook scripts with permissions', command: `ls -la ${repo}/.factory/hooks/`, riskLevel: 'low' }),
  buildLog: () => tools.Execute({ summary: 'List build-log files with sizes', command: `ls -la ${repo}/build-log/2026-10-22/ | head -20`, riskLevel: 'low' }),
  wtBuildLog: () => tools.Execute({ summary: 'List worktree build-log', command: `ls -la /home/user/code/EllyaOrg/projects/dalimaray/observatory-wt/s/build-log/ 2>&1; ls -la /home/user/code/EllyaOrg/projects/dalimaray/observatory-wt/s/build-log/*/ 2>&1 | head -20`, riskLevel: 'low' }),
  jq: () => tools.Execute({ summary: 'Check jq availability', command: 'which jq; jq --version; echo "exit=$?"', riskLevel: 'low' }),
  droid: () => tools.Execute({ summary: 'Check droid version', command: 'droid --version 2>&1; echo "exit=$?"', riskLevel: 'low' }),
};
const names = Object.keys(calls);
const rs = await Promise.allSettled(names.map(n => calls[n]()));
rs.forEach((r, i) => text(`## ${names[i]}\n${r.status === 'fulfilled' ? (typeof r.value === 'string' ? r.value : JSON.stringify(r.value)) : String(r.reason)}`));

const repo = '/home/user/code/EllyaOrg/projects/dalimaray/droid-observatory';
const calls = {
  script: () => tools.Read({ file_path: `${repo}/.factory/hooks/log-tool-call.sh`, line_numbers: true }),
  guard: () => tools.Read({ file_path: `${repo}/.factory/hooks/guard-git.sh`, line_numbers: true }),
  factoryDir: () => tools.Execute({ summary: 'List .factory directory', command: `ls -la ${repo}/.factory/`, riskLevel: 'low' }),
  grepHooks: () => tools.Grep({ pattern: 'log-tool-call|PostToolUse', path: repo, output_mode: 'content', line_numbers: true, glob_pattern: '!build-log/**' }),
  userSettings: () => tools.Execute({ summary: 'Show user-level factory settings hooks', command: `ls -la ~/.factory/ 2>&1 | head -30; echo ---; cat ~/.factory/settings.json 2>&1`, riskLevel: 'low' }),
  readme: () => tools.Read({ file_path: `${repo}/build-log/README.md` }),
};
const names = Object.keys(calls);
const rs = await Promise.allSettled(names.map(n => calls[n]()));
rs.forEach((r, i) => text(`## ${names[i]}\n${r.status === 'fulfilled' ? (typeof r.value === 'string' ? r.value : JSON.stringify(r.value, null, 1)) : String(r.reason)}`));

const rs = await Promise.allSettled([
  tools.Execute({ summary: 'List droid logs', command: `ls -laR ~/.factory/logs | head -40`, riskLevel: 'low' }),
  tools.Execute({ summary: 'Grep droid logs for hook errors', command: `grep -rn -i 'Cannot index\\|log-tool-call\\|PostToolUse' ~/.factory/logs 2>/dev/null | head -20; echo "grep rc=$?"`, riskLevel: 'low' }),
  tools.Execute({ summary: 'Grep session transcripts for hook output', command: `grep -rl 'Cannot index' ~/.factory/sessions 2>/dev/null | head -5; echo "rc=$?"; grep -rho 'Cannot index [a-z]* with string "[a-zA-Z]*"' ~/.factory/sessions 2>/dev/null | sort | uniq -c | head`, riskLevel: 'low' }),
]);
const names = ['logs dir', 'logs grep', 'sessions grep'];
rs.forEach((r, i) => text(`## ${names[i]}\n${r.status === 'fulfilled' ? `exit ${r.value.exitCode}\n${r.value.output}` : String(r.reason)}`));

